#include <iostream> 
using namespace std;  
long F(long x) {
    return 2*(x*x-100)*(x*x-100)+5;
}
int main() {
    long a, b, t, M, R;
    a = -20; b = 20;
    M = a; R = F(a);
    for (t = a; t <= b; t++) {
       if (F(t) < R) { 
          M = t; R = F(t);
       }
    }
    cout << M + 27 << endl;
    return 0; 
}
